import numpy as np,itertools
L=open('opt_gfn2.xyz').read().split('\n')
n=int(L[0]);S=[];P=[]
for l in L[2:2+n]:
    p=l.split();S.append(p[0]);P.append([float(x) for x in p[1:4]])
P=np.array(P)
cov={'H':0.31,'C':0.76,'N':0.71,'Si':1.11,'Co':1.26}
import collections
bl=collections.defaultdict(list)
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(P[i]-P[j])
    if d<1.3*(cov[S[i]]+cov[S[j]]):
        bl[i].append(j);bl[j].append(i)
for i in range(n):
    if S[i]!='H': print(i,S[i],len(bl[i]),[(j,S[j],round(np.linalg.norm(P[i]-P[j]),2)) for j in bl[i] if S[j]!='H'])
"

